const input = $input.first().json ?? {};

const companyId = String(
  input.company_id ??
  input.companyId ??
  input.metadata?.company_id ??
  input.metadata?.companyId ??
  'jayeola'
).trim();

const datasetId = String(
  input.dataset_id ??
  input.datasetId ??
  input.metadata?.dataset_id ??
  input.metadata?.datasetId ??
  ''
).trim();

const sessionId = String(input.sessionId ?? '').trim();
const chatInput = String(input.chatInput ?? input.message ?? '').trim();

if (!companyId) throw new Error('Missing required company_id.');
if (!sessionId) throw new Error('Missing required sessionId.');
if (!chatInput) throw new Error('Missing chatInput.');

const metadataFilter = { company_id: companyId };
if (datasetId) metadataFilter.dataset_id = datasetId;

return [{
  json: {
    ...input,
    company_id: companyId,
    dataset_id: datasetId,
    sessionId,
    chatInput,
    memory_key: `${companyId}:${sessionId}`,
    metadata_filter: metadataFilter,
  },
}];
